#!/usr/bin/env bash
# The README's flow diagram (docs/assets/flow.svg) is generated by docs/assets/flow.py. A generated file
# that is also committed must match its source (AGENTS.md: derived values have one source of truth), so
# a hand edit to the SVG, or a generator change without regenerating, fails here.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
if out="$(python3 "$ROOT/docs/assets/flow.py" --check 2>&1)"; then
	printf 'ok - %s\n' "$out"
else
	printf 'not ok - %s\n' "$out" >&2
	exit 1
fi
